#!/usr/bin/env python3
"""Offline compiler for complete microservice invocation path policies.

Reads one JSON request per physical input line, validates each request through
staged checks, compiles the accepted path language into the canonical minimal
DFA (with per-state viability distances), and prints exactly one JSON object
per input line.
"""

import json
import math
import sys

LINE_BYTE_LIMIT = 1048576
NEST_LIMIT = 64
TUPLE_CAP = 20000

MAX_SERVICES = 24
MAX_SERVICE_SCALARS = 64
MAX_RULES = 32
MAX_EXPR_NODES = 256
MAX_ARGS = 32
MAX_ATOM_PATH = 16
MAX_ATOMS = 10
MAX_QUERIES = 256
MAX_QUERY_PATH = 4096
MAX_QUERY_TOTAL = 16384

E_JSON = '{"ok":false,"error":"E_JSON"}'
E_SCHEMA = '{"ok":false,"error":"E_SCHEMA"}'
E_LIMIT = '{"ok":false,"error":"E_LIMIT"}'
E_COMPLEXITY = '{"ok":false,"error":"E_COMPLEXITY"}'


class JsonError(Exception):
    pass


class SchemaError(Exception):
    pass


class LimitError(Exception):
    pass


class ComplexityError(Exception):
    pass


# ---------------------------------------------------------------------------
# Stage 2: bounded nesting pre-scan of the decoded text.
# ---------------------------------------------------------------------------

def scan_depth(text):
    """Return True unless bracket nesting exceeds the wire limit.

    Double-quoted strings and backslash escapes are honoured exactly as JSON
    does; delimiter kinds are not matched.  Depth never drops below zero.
    """
    depth = 0
    instr = False
    esc = False
    for ch in text:
        if instr:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                instr = False
        elif ch == '"':
            instr = True
        elif ch == '{' or ch == '[':
            depth += 1
            if depth > NEST_LIMIT:
                return False
        elif ch == '}' or ch == ']':
            if depth:
                depth -= 1
    return True


# ---------------------------------------------------------------------------
# Stage 3: JSON parsing rejecting duplicate keys and numeric constants.
# ---------------------------------------------------------------------------

def _pairs_hook(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise ValueError('duplicate object key')
        obj[key] = value
    return obj


def _bad_constant(_name):
    raise ValueError('forbidden numeric constant')


def parse_json(text):
    return json.loads(text, object_pairs_hook=_pairs_hook,
                      parse_constant=_bad_constant)


def scan_values(root):
    """Check scalar validity of every string, key and number in the document."""
    bad_str = False
    bad_num = False
    stack = [root]
    while stack:
        node = stack.pop()
        kind = type(node)
        if kind is str:
            try:
                node.encode('utf-8')
            except UnicodeEncodeError:
                bad_str = True
        elif kind is list:
            if node:
                stack.extend(node)
        elif kind is dict:
            for key, value in node.items():
                try:
                    key.encode('utf-8')
                except UnicodeEncodeError:
                    bad_str = True
                stack.append(value)
        elif kind is float:
            if not math.isfinite(node):
                bad_num = True
    if bad_num:
        raise JsonError()
    if bad_str:
        raise SchemaError()


# ---------------------------------------------------------------------------
# Stage 4/5: schema and declared size limits.
# ---------------------------------------------------------------------------

ATOM_OPS = ('match', 'startswith', 'endswith', 'contains')
REQUEST_KEYS = frozenset(('services', 'rules', 'queries'))


def parse_expr(node, ctx):
    """Validate an expression and convert it to an internal tree node."""
    ctx['nodes'] += 1
    if ctx['nodes'] > MAX_EXPR_NODES:
        ctx['node_overflow'] = True
    if type(node) is not dict:
        raise SchemaError()
    op = node.get('op')
    if type(op) is not str:
        raise SchemaError()
    if op == 'true' or op == 'false':
        if len(node) != 1:
            raise SchemaError()
        return (0, op == 'true')
    if op in ATOM_OPS:
        if len(node) != 2 or 'path' not in node:
            raise SchemaError()
        path = node['path']
        if type(path) is not list:
            raise SchemaError()
        if len(path) > MAX_ATOM_PATH:
            ctx['long_atom_path'] = True
        ids = []
        index_of = ctx['tokidx'].get
        for token in path:
            if type(token) is not str:
                raise SchemaError()
            idx = index_of(token)
            if idx is None:
                raise SchemaError()
            ids.append(idx)
        key = (op, tuple(ids))
        atom_id = ctx['akey'].get(key)
        if atom_id is None:
            atom_id = len(ctx['atoms'])
            ctx['akey'][key] = atom_id
            ctx['atoms'].append(key)
            if atom_id >= MAX_ATOMS:
                ctx['atom_overflow'] = True
        return (1, atom_id)
    if op == 'not':
        if len(node) != 2 or 'arg' not in node:
            raise SchemaError()
        return (2, parse_expr(node['arg'], ctx))
    if op == 'and' or op == 'or':
        if len(node) != 2 or 'args' not in node:
            raise SchemaError()
        args = node['args']
        if type(args) is not list:
            raise SchemaError()
        if len(args) > MAX_ARGS:
            ctx['wide_args'] = True
        return (3 if op == 'and' else 4,
                [parse_expr(arg, ctx) for arg in args])
    raise SchemaError()


def parse_request(obj):
    """Validate structure, then declared size limits.  Returns compiled input."""
    if type(obj) is not dict:
        raise SchemaError()
    if frozenset(obj) != REQUEST_KEYS:
        raise SchemaError()

    services = obj['services']
    if type(services) is not list:
        raise SchemaError()
    tokidx = {}
    names = []
    too_many_services = len(services) > MAX_SERVICES
    service_too_long = False
    for name in services:
        if type(name) is not str:
            raise SchemaError()
        if not name or name in tokidx:
            raise SchemaError()
        tokidx[name] = len(names)
        names.append(name)
        if len(name) > MAX_SERVICE_SCALARS:
            service_too_long = True

    rules_json = obj['rules']
    if type(rules_json) is not list:
        raise SchemaError()
    too_many_rules = len(rules_json) > MAX_RULES

    ctx = {
        'tokidx': tokidx,
        'akey': {},
        'atoms': [],
        'nodes': 0,
        'node_overflow': False,
        'atom_overflow': False,
        'long_atom_path': False,
        'wide_args': False,
    }
    rules = []
    for rule in rules_json:
        if type(rule) is not dict:
            raise SchemaError()
        if len(rule) != 2 or 'action' not in rule or 'when' not in rule:
            raise SchemaError()
        action = rule['action']
        if type(action) is not str:
            raise SchemaError()
        if action != 'allow' and action != 'drop':
            raise SchemaError()
        rules.append((action == 'allow', parse_expr(rule['when'], ctx)))

    queries_json = obj['queries']
    if type(queries_json) is not list:
        raise SchemaError()
    too_many_queries = len(queries_json) > MAX_QUERIES
    query_too_long = False
    queries = []
    index_of = tokidx.get
    total_query_tokens = 0
    for path in queries_json:
        if type(path) is not list:
            raise SchemaError()
        if len(path) > MAX_QUERY_PATH:
            query_too_long = True
        total_query_tokens += len(path)
        row = []
        for token in path:
            if type(token) is not str:
                raise SchemaError()
            idx = index_of(token)
            if idx is None:
                raise SchemaError()
            row.append(idx)
        queries.append(row)
    if total_query_tokens > MAX_QUERY_TOTAL:
        query_too_long = True

    if (too_many_services or service_too_long or too_many_rules
            or too_many_queries or query_too_long or ctx['node_overflow']
            or ctx['atom_overflow'] or ctx['long_atom_path']
            or ctx['wide_args']):
        raise LimitError()

    return {
        'services': names,
        'ttl': tokidx,
        'rules': rules,
        'queries': queries,
        'atoms': ctx['atoms'],
    }


# ---------------------------------------------------------------------------
# Atomic monitors.
# ---------------------------------------------------------------------------

def build_monitor(op, pattern, sigma):
    """Return (truth_state, rows) with rows[state][token] -> state.

    truth_state is the single state in which the atom holds.  States are
    numbered exactly as the specification describes.
    """
    m = len(pattern)
    if op == 'match' or op == 'startswith':
        fail = m + 1
        rows = [[fail] * sigma for _ in range(m + 2)]
        for k in range(m):
            target = k + 1
            want = pattern[k]
            row = rows[k]
            for t in range(sigma):
                row[t] = target if t == want else fail
        if op == 'startswith':
            rows[m] = [m] * sigma
        return m, rows

    # endswith / contains share the border automaton.
    if op == 'contains':
        if m == 0:
            return 0, [[0] * sigma]
        rows = [[0] * sigma for _ in range(m + 1)]
        top = m - 1
    else:
        rows = [[0] * sigma for _ in range(m + 1)]
        top = m
    for k in range(top + 1):
        base = pattern[:k]
        row = rows[k]
        longest = k + 1
        if longest > m:
            longest = m
        for t in range(sigma):
            cur = base + [t]
            best = 0
            for j in range(longest, 0, -1):
                if cur[k + 1 - j:] == pattern[:j]:
                    best = j
                    break
            row[t] = best
    if op == 'contains':
        rows[m] = [m] * sigma
    return m, rows


def monitor_reach(rows):
    seen = {0}
    stack = [0]
    while stack:
        state = stack.pop()
        for target in rows[state]:
            if target not in seen:
                seen.add(target)
                stack.append(target)
    return seen


# ---------------------------------------------------------------------------
# Stage 6: monitor product complexity, and the language evaluation.
# ---------------------------------------------------------------------------

def build_product(atoms, sigma):
    """Explore the synchronous monitor product.

    Returns (order, trans, const_truth, kept_truth, nrep, col_of) or raises
    ComplexityError when more than TUPLE_CAP tuples are reachable.
    """
    kept = []
    const_truth = {}
    for idx, (op, pattern) in enumerate(atoms):
        truth_state, rows = build_monitor(op, pattern, sigma)
        reach = monitor_reach(rows)
        if len(reach) == 1:
            const_truth[idx] = (next(iter(reach)) == truth_state)
        else:
            kept.append((idx, truth_state, rows, sorted(reach)))

    nkeep = len(kept)
    rep_of = [0] * sigma
    colsig = {}
    reps = []
    for t in range(sigma):
        key = tuple([tuple([rows[s][t] for s in reach])
                     for (_idx, _truth, rows, reach) in kept])
        head = colsig.get(key)
        if head is None:
            head = t
            colsig[key] = head
            reps.append(head)
        rep_of[t] = head
    pos_of_rep = {}
    for position, head in enumerate(reps):
        pos_of_rep[head] = position
    col_of = [pos_of_rep[rep_of[t]] for t in range(sigma)]
    nrep = len(reps)

    rowtabs = []
    truth = []
    for (idx, truth_state, rows, reach) in kept:
        reduced = [None] * len(rows)
        for state in reach:
            row = rows[state]
            reduced[state] = [row[t] for t in reps]
        rowtabs.append(reduced)
        truth.append(truth_state)

    init = (0,) * nkeep
    seen = {init: 0}
    order = [init]
    trans = []
    if nkeep:
        index = 0
        while index < len(order):
            current = order[index]
            index += 1
            here = [rowtabs[j][current[j]] for j in range(nkeep)]
            out = []
            append = out.append
            for column in zip(*here):
                pid = seen.get(column)
                if pid is None:
                    if len(order) >= TUPLE_CAP:
                        raise ComplexityError()
                    pid = len(order)
                    seen[column] = pid
                    order.append(column)
                append(pid)
            trans.append(out)
    else:
        trans.append([0] * nrep)

    return order, trans, const_truth, kept, truth, nrep, col_of


def evaluate_language(rules, const_truth, kept, nkeep):
    """Return an integer over all atom-truth masks: bit m set iff acceptance."""
    total_masks = 1 << nkeep
    full = (1 << total_masks) - 1
    leaf = []
    for j in range(nkeep):
        bit = 1 << j
        value = 0
        for mask in range(total_masks):
            if mask & bit:
                value |= 1 << mask
        leaf.append(value)
    bitpos = {}
    for j, (idx, _truth, _rows, _reach) in enumerate(kept):
        bitpos[idx] = j

    def ev(node):
        kind = node[0]
        if kind == 0:
            return full if node[1] else 0
        if kind == 1:
            const = const_truth.get(node[1])
            if const is not None:
                return full if const else 0
            return leaf[bitpos[node[1]]]
        if kind == 2:
            return full ^ ev(node[1])
        if kind == 3:
            value = full
            for child in node[1]:
                value &= ev(child)
                if not value:
                    return 0
            return value
        value = 0
        for child in node[1]:
            value |= ev(child)
            if value == full:
                return full
        return value

    allow_any = 0
    drop_any = 0
    for is_allow, root in rules:
        value = ev(root)
        if is_allow:
            allow_any |= value
        else:
            drop_any |= value
    return allow_any & (full ^ drop_any)


# ---------------------------------------------------------------------------
# DFA minimization (Hopcroft partition refinement).
# ---------------------------------------------------------------------------

def minimize(nstates, nsym, trans, acc):
    """Return class_of: state -> class index, with stable class indices."""
    if nstates <= 1:
        return [0] * max(nstates, 0)

    rev = []
    for a in range(nsym):
        counts = [0] * (nstates + 1)
        for s in range(nstates):
            counts[trans[s][a] + 1] += 1
        for u in range(nstates):
            counts[u + 1] += counts[u]
        flat = [0] * counts[nstates]
        cursor = counts[:]
        for s in range(nstates):
            u = trans[s][a]
            p = cursor[u]
            flat[p] = s
            cursor[u] = p + 1
        rev.append((counts, flat))

    final = {s for s in range(nstates) if acc[s]}
    nonfinal = set(range(nstates)) - final
    blocks = []
    if final:
        blocks.append(final)
    if nonfinal:
        blocks.append(nonfinal)
    class_of = [0] * nstates
    for position, block in enumerate(blocks):
        for state in block:
            class_of[state] = position
    work = set(range(len(blocks)))

    while work:
        pick = work.pop()
        splitter = list(blocks[pick])
        for a in range(nsym):
            counts, flat = rev[a]
            into = set()
            absorb = into.update
            for u in splitter:
                low = counts[u]
                high = counts[u + 1]
                if low != high:
                    absorb(flat[low:high])
            if not into:
                continue
            members = {}
            sizes = {}
            for state in into:
                block_id = class_of[state]
                bucket = members.get(block_id)
                if bucket is None:
                    members[block_id] = [state]
                    sizes[block_id] = 1
                else:
                    bucket.append(state)
                    sizes[block_id] += 1
            for block_id, moved in members.items():
                block = blocks[block_id]
                if sizes[block_id] == len(block):
                    continue
                fresh = len(blocks)
                blocks.append(set(moved))
                block.difference_update(moved)
                for state in moved:
                    class_of[state] = fresh
                if block_id in work:
                    work.add(fresh)
                elif len(moved) <= len(block):
                    work.add(fresh)
                else:
                    work.add(block_id)
    return class_of


# ---------------------------------------------------------------------------
# Full compilation.
# ---------------------------------------------------------------------------

def compile_bundle(request):
    services = request['services']
    rules = request['rules']
    queries = request['queries']
    atoms = request['atoms']
    sigma = len(services)

    order, trans, const_truth, kept, truth, nrep, col_of = build_product(
        atoms, sigma)
    nkeep = len(kept)

    language = evaluate_language(rules, const_truth, kept, nkeep)

    nstates = len(order)
    acc = bytearray(nstates)
    if language:
        by_mask = [(language >> mask) & 1 for mask in range(1 << nkeep)]
        for pid in range(nstates):
            current = order[pid]
            mask = 0
            for j in range(nkeep):
                if current[j] == truth[j]:
                    mask |= 1 << j
            acc[pid] = by_mask[mask]

    # Co-accessibility: prefixes that can still reach an accepting state.
    preds = [[] for _ in range(nstates)]
    for pid in range(nstates):
        for target in trans[pid]:
            preds[target].append(pid)
    coaccessible = bytearray(nstates)
    stack = [pid for pid in range(nstates) if acc[pid]]
    for pid in stack:
        coaccessible[pid] = 1
    while stack:
        state = stack.pop()
        for parent in preds[state]:
            if not coaccessible[parent]:
                coaccessible[parent] = 1
                stack.append(parent)

    live = [pid for pid in range(nstates) if coaccessible[pid]]
    if not live:
        accept_out = [False]
        full_rows = [[0] * sigma]
        dist = [None]
    else:
        position = {}
        for i, pid in enumerate(live):
            position[pid] = i
        nlive = len(live)
        dead = nlive
        nmin = nlive + 1
        min_trans = []
        for pid in live:
            row = []
            for target in trans[pid]:
                place = position.get(target)
                row.append(dead if place is None else place)
            min_trans.append(row)
        min_trans.append([dead] * nrep)
        min_acc = bytearray(nmin)
        for i, pid in enumerate(live):
            min_acc[i] = acc[pid]

        class_of = minimize(nmin, nrep, min_trans, min_acc)

        representative = {}
        for state in range(nmin):
            klass = class_of[state]
            if klass not in representative:
                representative[klass] = state
        start_class = class_of[0]

        # Canonical breadth-first numbering over the quotient.
        number = {start_class: 0}
        sequence = [start_class]
        rows_reduced = []
        accept_out = []
        head = 0
        while head < len(sequence):
            klass = sequence[head]
            head += 1
            state = representative[klass]
            row = []
            for target in min_trans[state]:
                target_class = class_of[target]
                num = number.get(target_class)
                if num is None:
                    num = len(sequence)
                    number[target_class] = num
                    sequence.append(target_class)
                row.append(num)
            rows_reduced.append(row)
            accept_out.append(bool(min_acc[state]))

        nfinal = len(sequence)
        full_rows = [[row[c] for c in col_of] for row in rows_reduced]

        # Distances: minimum extra tokens to reach an accepting state.
        dist = [None] * nfinal
        back = [[] for _ in range(nfinal)]
        for state in range(nfinal):
            for target in rows_reduced[state]:
                back[target].append(state)
        queue = [state for state in range(nfinal) if accept_out[state]]
        for state in queue:
            dist[state] = 0
        head = 0
        while head < len(queue):
            state = queue[head]
            head += 1
            step = dist[state] + 1
            for parent in back[state]:
                if dist[parent] is None:
                    dist[parent] = step
                    queue.append(parent)

    results = []
    for path in queries:
        state = 0
        for token in path:
            state = full_rows[state][token]
        results.append((state, accept_out[state], dist[state]))

    return serialize(accept_out, full_rows, dist, results)


def word(value):
    return 'true' if value else 'false'


def serialize(accept, rows, dist, results):
    parts = ['{"ok":true,"dfa":{"start":0,"accept":[']
    parts.append(','.join([word(a) for a in accept]))
    parts.append('],"next":[')
    first = True
    for row in rows:
        if first:
            first = False
        else:
            parts.append(',')
        parts.append('[' + ','.join([str(x) for x in row]) + ']')
    parts.append('],"distance":[')
    parts.append(','.join(['null' if d is None else str(d) for d in dist]))
    parts.append(']},"queries":[')
    first = True
    for state, allow, value in results:
        if first:
            first = False
        else:
            parts.append(',')
        text = 'null' if value is None else str(value)
        parts.append('{"state":%d,"allow":%s,"distance":%s}'
                     % (state, word(allow), text))
    parts.append(']}\n')
    return ''.join(parts)


# ---------------------------------------------------------------------------
# Pipeline.
# ---------------------------------------------------------------------------

def process(raw):
    if len(raw) > LINE_BYTE_LIMIT:
        return E_LIMIT
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        return E_JSON
    if not scan_depth(text):
        return E_LIMIT
    try:
        obj = parse_json(text)
    except Exception:
        return E_JSON
    try:
        scan_values(obj)
        request = parse_request(obj)
    except JsonError:
        return E_JSON
    except SchemaError:
        return E_SCHEMA
    except LimitError:
        return E_LIMIT
    try:
        return compile_bundle(request)
    except ComplexityError:
        return E_COMPLEXITY


def main():
    data = sys.stdin.buffer.read()
    if not data:
        return
    lines = data.split(b'\n')
    if lines[-1] == b'':
        lines.pop()
    out = []
    for raw in lines:
        try:
            out.append(process(raw))
        except Exception:
            out.append(E_JSON)
    sys.stdout.write(''.join([chunk + '\n' for chunk in out]))


if __name__ == '__main__':
    main()
